// Extrai o texto do CSV e converte em JSON estruturado
const item = $input.first().json;
let rawCsv = '';

if (typeof item === 'string') {
  rawCsv = item;
} else if (item.data && typeof item.data === 'string') {
  rawCsv = item.data;
} else {
  rawCsv = Object.keys(item).join(',');
}

const lines = rawCsv.trim().split(/\r?\n/);
const headers = lines[0].split(',').map(h => h.trim());

const investimentos = [];
for (let i = 1; i < lines.length; i++) {
  const row = lines[i].trim();
  if (!row) continue;
  const values = row.split(',').map(v => v.trim());
  const obj = {};
  headers.forEach((h, idx) => {
    obj[h] = values[idx] || '';
  });
  investimentos.push(obj);
}

return [{
  json: {
    investimentos: investimentos
  }
}];

// ETAPA 4 (MVP): Cruzamento de Perfis e Geração de Mensagens Estáticas
const mergedData = $input.first().json;
const clientes = mergedData.body?.clientes || mergedData.clientes || [];
const investimentos = mergedData.investimentos || [];

const clientesProcessados = clientes.map(cliente => {
  const perfilCliente = (cliente.perfil || '').toLowerCase().trim();
  const opcoes = investimentos.filter(inv => 
    (inv.perfil || '').toLowerCase().trim() === perfilCliente
  );

  const listaOpcoesTexto = opcoes.map(op => `${op.produto} (Rentabilidade: ${op.rentabilidade}, Mín: R$ ${op.minimo})`).join('; ');

  let mensagem = '';
  if (perfilCliente === 'conservador') {
    mensagem = `Olá, ${cliente.nome}! Identificamos seu perfil CONSERVADOR com foco absoluto em segurança e preservação de capital. Considerando seu saldo disponível de ${cliente.saldo}, recomendamos aplicar em produtos de baixo risco com liquidez: ${listaOpcoesTexto}.`;
  } else if (perfilCliente === 'moderado') {
    mensagem = `Olá, ${cliente.nome}! Com base no seu perfil MODERADO, buscando equilíbrio entre segurança e rentabilidade, recomendamos alocar seu saldo de ${cliente.saldo} de forma diversificada em: ${listaOpcoesTexto}.`;
  } else if (perfilCliente === 'arrojado') {
    mensagem = `Olá, ${cliente.nome}! Sendo um investidor de perfil ARROJADO focado em maior potencial de retorno e tolerância a risco, sugerimos alocar seu saldo de ${cliente.saldo} nas seguintes oportunidades de renda variável: ${listaOpcoesTexto}.`;
  } else {
    mensagem = `Olá, ${cliente.nome}! Analisamos seu saldo de ${cliente.saldo} e temos opções personalizadas para o seu momento financeiro.`;
  }

  return {
    nome: cliente.nome,
    email: cliente.email,
    saldo: cliente.saldo,
    perfil: cliente.perfil,
    recomendacoes: opcoes,
    mensagem: mensagem
  };
});

return [{
  json: {
    sucesso: true,
    total_processado: clientesProcessados.length,
    clientes: clientesProcessados
  }
}];
